import { useLayoutEffect, useRef, useState } from "react";
import { Excalidraw, getCommonBounds, restoreElements } from "@excalidraw/excalidraw";
import "@excalidraw/excalidraw/index.css";
// Generated by tools/build_timeline.py - edit the paper list there, not this file.
import timelineElementsRaw from "../data/research_papers_timeline_elements.json";

// restoreElements fills defaults, repairs invalid indices, and re-measures text with the real font.
const timelineElements = restoreElements(timelineElementsRaw as any, null, { refreshDimensions: true });
const [minX, minY, maxX, maxY] = getCommonBounds(timelineElements);
const contentW = maxX - minX;
const contentH = maxY - minY;

const PAD = 16; // breathing room around the diagram
const FOOTER = 56; // Excalidraw's bottom menu bar overlays the canvas

interface Box {
  column: number; // width of the article column we sit in
  width: number; // width we actually use (may break out of the column)
}

export function ExcalidrawTimeline() {
  const slotRef = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState<Box | null>(null);

  // Measure before mounting Excalidraw so the fitted view goes into initialData
  // (fitting after mount races Excalidraw's scene init and StrictMode's remount).
  // A wide timeline is cramped in the reading column, so break out to the full width of
  // <main> between the side panels, capped at the diagram's natural size.
  useLayoutEffect(() => {
    const slot = slotRef.current!;
    const main = slot.closest("main");
    let avail = slot.clientWidth;
    if (main) {
      const cs = getComputedStyle(main);
      avail = main.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
    }
    setBox({ column: slot.clientWidth, width: Math.min(avail, Math.ceil(contentW + 2 * PAD)) });
  }, []);

  const zoom = box ? Math.min(1, (box.width - 2 * PAD) / contentW) : 1;
  const height = Math.ceil(contentH * zoom + 2 * PAD + FOOTER);

  return (
    <div ref={slotRef} style={{ margin: "8px 0 24px" }}>
      {box && (
        <div
          style={{
            width: box.width,
            height,
            marginLeft: (box.column - box.width) / 2, // centre on the column, overhanging both sides
            border: "1px solid #e2e8f0",
            borderRadius: "12px",
            overflow: "hidden",
            backgroundColor: "#ffffff",
          }}
        >
          <Excalidraw
            initialData={{
              elements: timelineElements,
              appState: {
                viewBackgroundColor: "#ffffff",
                zoom: { value: zoom as any },
                // Screen x = (sceneX + scrollX) * zoom: centre horizontally, pin to the top.
                scrollX: (box.width / zoom - contentW) / 2 - minX,
                scrollY: PAD / zoom - minY,
              },
            }}
            viewModeEnabled={true}
            UIOptions={{
              canvasActions: {
                export: { saveFileToDisk: true },
                saveAsImage: true,
                loadScene: true,
                saveToActiveFile: false,
              },
            }}
          />
        </div>
      )}
    </div>
  );
}
